// Authored synthetic program approvals and labour snapshots, never municipal evidence.
import{createHash}from'node:crypto';
import{salarySerialized}from'../../assets/native-salary-catalog-model.js';
import{participationRuleKey}from'../../assets/own-period-participation-program.js';
import{MONTHLY_DAY_FACTS_VERSION,MONTHLY_DAY_SOURCE_VERSION,MONTHLY_DAY_POLICY_VERSION}from'../../assets/own-monthly-day-policy-model.js';
import{auxiliarySources}from'./own-payroll-auxiliary-synthetic.js';
import{syntheticParticipationBootstrap}from'./own-period-participation-synthetic.js';
export const uid=n=>`dddddddd-0000-4000-8000-${String(n).padStart(12,'0')}`;
export const hash=v=>createHash('sha256').update(salarySerialized(v)).digest('hex');
export const actorScope=(actor=3)=>({tenantId:uid(1),sourceBindingId:uid(2),membershipId:uid(actor),companyId:'101',scopeVersion:hash(['synthetic-current-scope',actor])});
const binding=(key,sourceKind,sourceField,unit)=>({agreementCode:'1',key,sourceKind,sourceField,unit,onMissing:'error',combine:'single',ruleReference:'Fuente exclusivamente sintética QA'});
const input=(key,unit)=>({op:'input',key,unit}),aux=code=>({op:'auxiliary',code,stage:'exact'});
export const qaRule=(code,nature,unit,expression,type='monthly',period='2026-10')=>({agreementCode:'1',code,nature,unit,validFrom:period,validUntil:period,liquidationTypes:[type],expression,rounding:{precision:unit==='money'?2:0,mode:'exact'},ruleReference:'Fórmula exclusivamente QA, no municipal'});
export function sourceFor(e,scope,period,{adopted=false}={}){const b=syntheticParticipationBootstrap(),participationSource={...b.source,period,version:hash(['synthetic-period-source',e.contractId,period]),fullPeriod:true,subject:{...b.source.subject,contractId:e.contractId,legajo:e.employeeNumber,identityToken:e.identityToken}};const v={version:MONTHLY_DAY_SOURCE_VERSION,scope:structuredClone(scope),contractId:e.contractId,identityToken:e.identityToken,period,employmentKind:adopted?'adopted':'native',participationSource,lifecycle:{version:hash(['synthetic-lifecycle',e.contractId]),revision:0,appliedAt:null,intervals:[{startDate:'2000-01-01',endDate:null}],today:'2026-10-16',status:'active',...(adopted?{datesVerified:true}:{})}};return{...v,sha256:hash(v)};}
export function seal(s){if(s.monthlyDays){for(const r of s.monthlyDays.records){const{sha256,...source}=r.source;r.source.sha256=hash(source);}const{complete,version,payloadSha256,...body}=s.monthlyDays;s.monthlyDays.payloadSha256=hash(body);s.monthlyDays.version=hash([MONTHLY_DAY_FACTS_VERSION,s.monthlyDays.payloadSha256]);}const p=s.periodParticipation;p.version=hash(['own-period-participation.v1',s.period,p.records]);s.population.version=hash({employees:s.population.employees,periodParticipation:p,...(s.monthlyDays?{monthlyDays:s.monthlyDays,monthlyDaysScope:s.monthlyDaysScope}:{})});return s;}
export function policySources(count=2){const s=auxiliarySources(count),p=s.programState.program.definition,period=s.period;s.monthly={complete:true,batches:[]};s.monthlyDaysScope=actorScope();s.programState.scopeVersion=s.monthlyDaysScope.scopeVersion;
 p.monthlyDaysVersion=MONTHLY_DAY_FACTS_VERSION;p.monthlyDaysPolicy={version:MONTHLY_DAY_POLICY_VERSION,basis:'verified_full_month',unit:'days',recognizedDays:'30',baseDays:'30',partial:'reject',reference:'Base30 confirmada; ejemplo exclusivamente QA'};
 p.rules=[qaRule('9100','remuneration','money',{op:'multiply',left:{op:'literal',unit:'money',value:'60'},right:{op:'divide',left:aux('9101'),right:aux('9102')}}),qaRule('9101','auxiliary','days',input('recognizedDays','days')),qaRule('9102','auxiliary','days',input('baseDays','days')),qaRule('9103','auxiliary','units',input('recognizedUnits','units')),qaRule('9104','auxiliary','units',input('baseUnits','units'))];
 p.bindings=[binding('recognizedDays','monthly_day_fact','recognizedDays','days'),binding('baseDays','monthly_day_fact','baseDays','days'),binding('recognizedUnits','period_fact','recognizedUnits','units'),binding('baseUnits','period_fact','baseUnits','units')];
 updateRules(s);
 s.periodParticipation={complete:true,version:hash('pending'),records:s.population.employees.map(e=>({contractId:e.contractId,identityToken:e.identityToken,fullPeriod:true,configuration:{version:hash(['no-individual-approval',e.contractId]),revision:0,definition:null,proposalId:null,approvalId:null,identityToken:null,sourceVersion:null}}))};
 const a=s.programState.program;s.monthlyDays={complete:true,monthlyDaysVersion:MONTHLY_DAY_FACTS_VERSION,version:hash('pending'),payloadSha256:hash('pending'),period,scope:s.monthlyDaysScope,programBasis:{programVersion:a.version,revision:a.revision,proposalId:a.proposalId,approvalId:a.approvalId,policy:structuredClone(p.monthlyDaysPolicy),policySha256:hash(p.monthlyDaysPolicy)},records:s.population.employees.map((e,i)=>({contractId:e.contractId,identityToken:e.identityToken,fullPeriod:true,recognizedDays:'30',baseDays:'30',authority:'approved_program_full_month',source:sourceFor(e,s.monthlyDaysScope,period,{adopted:i%2===1})}))};return seal(s);}
export function updateRules(s){const p=s.programState.program.definition;p.periodParticipation={version:'own-period-participation.v1',fullPeriod:'neutral_fraction',fixedValidity:'reject',treatments:p.rules.map(r=>({ruleKey:participationRuleKey(r),treatment:'declared_formula',reference:'La fórmulaQA declara su proporción sin segunda fracción'}))};s.programState.salaryCatalog.items=p.rules.map(r=>({kind:r.nature==='auxiliary'?'auxiliary':'concept',agreementCode:r.agreementCode,categoryCode:null,code:r.code,label:'Registro exclusivamente sintéticoQA '+r.code,nature:r.nature,unit:r.unit,precision:r.unit==='money'?2:0,value:null,validFrom:r.validFrom,validUntil:r.validUntil,ruleReference:'Metadata sintética; ninguna fórmula municipal',dependencies:[],active:true}));}
